package com.parksmart.config;
import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtUtil jwt; public JwtFilter(JwtUtil jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String sub=jwt.subject(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(sub,null,java.util.List.of()));}catch(Exception ignored){}chain.doFilter(req,res);} }